import Link from 'next/link'
import { useRouter } from 'next/router'

export const NAV_ITEMS = [
  { href: '/dashboard', label: 'Dashboard' },
  { href: '/workouts', label: 'Workouts' },
  { href: '/diet', label: 'Diet' },
  { href: '/progress', label: 'Progress' },
  { href: '/coach', label: 'Coach' },
  { href: '/settings', label: 'Settings' },
] as const

interface SidebarProps {
  tier: string
  onSignOut: () => void
}

export function Sidebar({ tier, onSignOut }: SidebarProps) {
  const router = useRouter()

  return (
    <aside
      className="flex shrink-0 flex-col border-navy-800 bg-navy-900
                 max-lg:w-full max-lg:border-b
                 lg:w-60 lg:border-r lg:border-b-0
                 p-4"
    >
      <Link
        href="/dashboard"
        className="focus-ring mb-6 flex min-tap items-center px-2 font-display text-xl text-white max-lg:mb-3"
      >
        Apex<span className="text-gold-400">Fitness</span>
      </Link>

      {/* Below `lg` the six destinations become a single horizontally
          scrollable strip, which is the only arrangement that keeps all of
          them one tap away on a phone without pinning 240px of width. */}
      <nav
        aria-label="Main"
        className="flex flex-1 gap-1 max-lg:-mx-4 max-lg:overflow-x-auto max-lg:px-4
                   lg:flex-col"
      >
        {NAV_ITEMS.map((item) => {
          const active = router.pathname === item.href
          return (
            <Link
              key={item.href}
              href={item.href}
              aria-current={active ? 'page' : undefined}
              className={`shrink-0 whitespace-nowrap rounded-md px-3 py-2 text-sm transition-colors ${
                active
                  ? 'bg-navy-800 text-emerald-500'
                  : 'text-slate-300 hover:bg-navy-800 hover:text-white'
              }`}
            >
              {item.label}
            </Link>
          )
        })}
      </nav>

      <div className="mt-4 border-t border-navy-800 pt-4">
        <p className="px-3 pb-2 text-xs uppercase tracking-wide text-slate-400">
          {tier === 'premium' ? 'Premium member' : 'Free plan'}
        </p>
        {tier !== 'premium' ? (
          <Link
            href="/checkout"
            className="mx-3 mb-2 block rounded-md bg-gold-500 px-3 py-2 text-center text-sm font-medium text-navy-950"
          >
            Go premium
          </Link>
        ) : null}
        <button
          type="button"
          onClick={onSignOut}
          className="w-full rounded-md px-3 py-2 text-left text-sm text-slate-400 hover:bg-navy-800 hover:text-white"
        >
          Sign out
        </button>
      </div>
    </aside>
  )
}
